import{_ as l,c as p,o as a,ah as e}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易尚氏學說例","description":"周易尚氏學 - 周易尚氏學說例","frontmatter":{"title":"周易尚氏學說例","description":"周易尚氏學 - 周易尚氏學說例"},"headers":[],"relativePath":"classics/shangshi/004.md","filePath":"classics/shangshi/004.md"}'),s={name:"classics/shangshi/004.md"};function t(r,i,n,c,_,o){return a(),p("div",null,[...i[0]||(i[0]=[e('<h1 id="周易尚氏學說例" tabindex="-1">周易尚氏學說例 <a class="header-anchor" href="#周易尚氏學說例" aria-label="Permalink to “周易尚氏學說例”">​</a></h1><ul><li><p>乾坤二卦為六十四卦之根本。其六爻爻辭。祇以明上下。別貴賤。及卦運之興衰。初終之時位。樹六十四卦之準則。至於有無應與當位不當位之恆例。皆未之及。而六爻之後。復贅以用九用六數語。皆所以明筮例。及用九用六之故。學者須於此先知之。</p></li><li><p>易辭本為佔辭。故其語在可解不可解之間。惟其在可解不可解之間。故能隨所感而曲中肆應不窮。所謂仁者見仁，智者見智也。此易理也。易理與義理不同。例如程傳說黃裳元吉。雲五尊位。臣居之則羿莽。女居之則女媧武氏。故聖人著為大戒。陳義可謂正大矣。而於易理則大背，以易辭並無著戒之意也。此編只明易理。至其用則任人感觸之。</p></li><li><p>卦名皆因卦象而生。卦名不解。因之卦爻辭亦不解。如睽為反目。謂兩目不相聽。故一目見為此。一目見為彼。三上爻辭是也。此義不知。遂多誤解。又如節為符節。合以取信。說文所謂竹約也。乃說者概釋為樽節制節。卦義既誤。故卦爻辭甘苦之義均不知。六十四卦如此者甚多。茲編所釋。先及諸卦得名之義。其名有沿革者。亦並考其異同。如睽歸藏作瞿。夬歸藏作規等是也。</p></li><li><p>說易之書。莫古於左傳國語。其所取象。當然無訛。乃清儒信漢儒。而遺左國。坎變巽。左氏曰。夫從風。以坎為夫也。曰震車也。曰車有震武。以震為車為武也。震變離。曰車說其輹。以震為輹也。尤要者。明夷之謙。即離變艮。左氏曰當鳥。是以艮為鳥也。鳥黔喙也。於是小過飛鳥之象有著。乃後人於此象均不識。依漢儒以震為夫。以幹為武。夫易師莫先於左氏。其可信較漢儒為何如。故茲編所取象。除以易證易外。首本之左傳國語。以明此最古最確之易象。</p></li><li><p>時訓為逸周書之專篇。書雲周公所作。其氣候皆以卦象為準。故卦氣圖與時訓不能相離。其所準易象。與易經所關最巨。如於屯曰雁北鄉。以屯上互艮為雁。於巽曰鴻雁來。亦以巽為鴻雁。而漸之六鴻象得解。以艮為蛤為蜃。艮外堅故與離同象。而易之貝象龜象得解。以兌為斧。以艮為巢為鷹。皆賴以解。易而用覆象半象尤精。如於復曰麋角解。震為鹿。艮為角。角覆在地。故日解。於鼎下曰半夏生。離為夏。巽為艹。初二半離。故曰半夏。而昔儒無知者。(除易林外)茲編所取象。除左國外。多以時訓為本。</p></li><li><p>焦氏易林。後儒皆知其言易象。然以象學失傳之故。莫有通其義者。如以坤為水。以兌為月。以艮為火。以巽為少妻。以兌為老婦。以正反兌正反震為爭訟。(爭訟即有言)為說卦所無。而皆為經中所有。說者因誤解經。而失其象。故於易林亦不能解。愚求之多年。亦無所入。後讀蒙之節雲。三夫共妻。莫適為雌。子無名氏。翁不可知。因節中爻震艮。上坎三男俱備。故曰三夫。祇下兌為女象。故曰三夫共妻。震為子。艮為名為翁。上坎為隱伏。故曰無。曰不可知。字字皆從易象生。由此以推。凡林詞皆豁然而解。故茲編取象。除左傳國語卦氣圖外。多本易林。</p></li><li><p>易中古文甚多。如場作易。 趑趄作次且。趾作止。佚作失等。不可勝數。先儒除晁說之外。知為古文者甚少。於是竟讀易為難易。失為得失。茲編非好異。凡易之古文。必仍其舊例。如需於血。即需於洫是也。</p></li><li><p>古書多音同通用。而易尤甚。如盤。作盤。作盤。作般。邅如。作驙如。甲坼。作甲宅。冶容。作野容。刑剭。作形渥。作刑屋。經綸。作經論。作經倫。羸。作虆。作累。作縲。作累之類。皆音同通借。無是非之可言。而世儒必以習見者為非。罕見者為是。似未觀其通。茲編反是。</p></li><li><p>易用覆象。如大過九五之枯楊。用覆巽。豐上六用覆艮。重門擊柝。以豫上震為覆艮。荀爽及虞翻皆知之。而不能推行。於是困之有言不信。蒙之再三瀆。用覆象者。遂永不得解。豈知左氏明夷之謙曰。於人為言。敗言為讒。謙上震。震為言。下艮震覆。故曰敗言。言相反故曰讒。易林本之。凡正反震正反兌相背者。不曰爭訟。即曰有言。於是困震之有言皆得解。此似我創言之。然仍左氏及易林所已言。我拾其說以證易耳。仍非我說也。</p></li><li><p>卦有卦情。中孚之鶴嗚子和。以中爻正反震相對也。故下之震鶴一鳴。三至五即如聲而反。故曰子和。(舊解不知子指反震皆自鳴自和)又如兌。朋友講習。以初至五。正覆兌相對。若對語然。故曰講習。早商兌。夬四之聞言不信。兌為耳。故曰聞。兌為言。幹亦為言。乃兌言向外。與幹言相背。故曰不信。此似我創解。然左傳歸妹之睽。曰西鄰責言。不可償也。歸妹兌為西。震為鄰。故曰西鄰。而震為言。震言外向。與兌言相背。故曰責言。與夬之聞言不信義同也。仍非我說也。</p></li><li><p>同此一爻。而爻辭吉凶不同。如頤六五曰。居貞吉。下又曰不可涉大川。家人九三曰。嗃嗃悔厲吉。下又曰婦子嘻嘻終吝。先儒無詳其故者。豈知爻有上下。由此爻上取。而象吉者。下取或兇。下取而象吉者。上取或兇。如漸九三婦孕不育兇。下又曰利禦寇是也。易詞如此者不可枚舉。此三爻特其例耳。治易者如明此例。則事半功倍。</p></li><li><p>易辭與他經不同。他經上下文多相屬。易則不然。因易辭皆由象生。觀某爻而得甲象。又觀某爻而得乙象。故易辭各有所指。上下句義不必相聯。如損彖曰利有攸往。指上九也。下又曰曷之用。二簋。可用享。震為簋。坤數二。故曰二簋。則指上下互卦也。又如困貞大人吉。以二五皆陽也。有言不信。以三至上正反兌相背也。舊解無知者。故於上下旬。常強為聯屬。致杈枒不合。茲編遇此。先指明易辭之說何爻何象。至其意義之不相屬者。亦必指明。此自為一義。</p></li><li><p>卦爻辭往往相反。如履彖曰不咥人。爻曰咥人兇。無妄彖曰不利有攸往。爻曰往吉。是也。又大象每相反以見義。如同人曰辨物。無妄曰時育萬物。是也。先儒無知其故者。豈知卦有卦義。爻有爻義。象有象義。絕不同也。</p></li><li><p>漢儒以象數解易。與春秋士大夫合。最為正軌。乃鄭玄於象之不知者。則用爻辰。取象於星宿。虞翻則用爻變。使變出某卦。以當其象。若此者亦不敢從也。</p></li><li><p>易義有絕不能解者。先儒雖強說之。實皆無當。如同人九四之吉。自象傳不能詳其故。小畜九二同。易義如此者多有。茲編遇之。必詳言其難解之故。偶有揣測。亦不敢自信也。</p></li><li><p>吳摯父先生易說。於大畜雲。凡陽之行。遇陰則通。遇陽則阻。故初二皆不進。而三利往。於節雲。易以陽在前為塞。陰在前為通。初之不出。以九二在前。二則可出而不出。故有失時之兇。此實全易之精髓。為二千年所未發。愚於易理粗有所入。實以此數語為之階。故特揭出。以尊師說。</p></li><li><p>眼前事物。皆為易理。俯取即是。例如雄雞與雄雞見則死鬥。驢馬尤甚。若有宿仇者。是何也。陽遇陽也。大畜初九曰。有厲利已。厲危已止也。初有應。但為二三所隔。遇敵故曰有厲。止而不動。則災免矣。象曰不犯災。正釋厲義也。乃舊解謂厲指四爻。厲若在四。尚何貴此應與乎。不識災即厲。命二變成坎。以取災象。豈知大壯初九。壯於趾徵兇。夬初九。壯於前趾往不勝。壯傷也。其故皆在陽遇陽。傷之與災。有何別乎。故夫目前易理。望之似淺。推之實深。昧厥目前。易雖一再言之。總不能知。</p></li></ul>',2)])])}const m=l(s,[["render",t]]);export{h as __pageData,m as default};
